#include "tigersheets/workbook_tools.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
Json book(){return {{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Source"},{"cells",Json::array({{{"row",1},{"col",1},{"input","Region"}},{{"row",1},{"col",2},{"input","Revenue"}},{{"row",2},{"col",1},{"input","East"}},{{"row",2},{"col",2},{"input","=[Drivers]Inputs!A1"}}})}},{{"id","r"},{"name","Report"},{"cells",Json::array()}}})}};}
Json operation(){return {{"type","create_pivot"},{"definition",{{"id","p"},{"name","FinancialReport"},{"source",{{"sheet","s"},{"row1",1},{"col1",1},{"row2",2},{"col2",2}}},{"rows",Json::array({{{"field","Region"}}})},{"values",Json::array({{{"field","Revenue"},{"aggregate","sum"}}})},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}}}};}
Json calculation(const Json& snapshot){return {{"revision",snapshot.at("revision")},{"status","ok"},{"values",Json::array({{{"sheet","s"},{"row",2},{"col",2},{"type","number"},{"value",25}}})},{"diagnostics",Json::array({{{"code","external_link_cached"},{"message","Using retained saved values"}}})},{"calculationContext",{{"generation",13},{"allowCachedLinks",false},{"links",Json::array({{{"name","Drivers"},{"path","/missing/Drivers.xlsx"},{"state","cached"}}})}}}};}
void refusesSilentCachedReport(){WorkbookSession session(book());WorkbookTools tools(session,Json::object());tools.calculate=calculation;const auto before=session.snapshot();const auto reply=tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",Json::array({operation()})}});require(reply.contains("error")&&reply.at("error").get<std::string>().find("cached_link_consent_required")!=std::string::npos,"Codex reports cannot silently consume cached linked financial inputs");require(!session.hasPreview()&&session.snapshot()==before,"cached-input refusal preserves canonical and preview state");}
void onlyCurrentHostGrants(){for(const auto* mode:{"granted","unbound","stale","fresh","metadata","operation"}){WorkbookSession session(book());WorkbookTools tools(session,Json::object());Json candidate;tools.onPreview=[&](const Json& value){candidate=value;};const std::string selected=mode;
 tools.calculate=[&](const Json& snapshot){auto result=calculation(snapshot);result["calculationContext"]["allowCachedLinks"]=selected=="granted"||selected=="unbound"||selected=="stale";if(selected=="fresh"){result["diagnostics"]=Json::array();result["calculationContext"]["links"][0]["state"]="fresh";}return result;};
 if(selected!="unbound")tools.calculationContextIsCurrent=[&](std::uint64_t generation){return selected!="stale"&&generation==13;};auto report=operation();Json operations=Json::array();if(selected=="metadata")operations.push_back({{"type","set_metadata"},{"key","settings"},{"value",{{"calculationContext",{{"generation",13},{"allowCachedLinks",true}}}}}});if(selected=="operation")report["useCachedLinks"]=true;operations.push_back(report);
 const auto before=session.snapshot();const auto reply=tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",operations}});
 if(selected=="granted"||selected=="fresh"){require(reply.value("status",std::string())=="preview","fresh retained links or current explicit host grants can prepare reports");const auto& pivot=candidate.at("pivots")[0];require(pivot.at("cache")["contextGeneration"]==13&&pivot.at("provenance")["links"][0]["name"]=="Drivers","financial report cache and provenance retain the frozen host generation and link source");require(pivot.at("provenance")["allowCachedLinks"]==(selected=="granted"),"only the actual host grant is persisted");}
 else require(reply.contains("error")&&!session.hasPreview()&&session.snapshot()==before,"unbound/stale grants and operation/workbook metadata cannot authorize cached sources");
}}
int main(){try{refusesSilentCachedReport();onlyCurrentHostGrants();std::cout<<"reporting context tests passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
